package com.ecommerce.cart.config;
import com.ecommerce.cart.security.*; import org.springframework.context.annotation.*; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
@Configuration public class SecurityConfig {@Bean SecurityFilterChain chain(HttpSecurity h,RateLimitFilter rate,JwtFilter jwt)throws Exception{return h.csrf(c->c.disable()).httpBasic(c->c.disable()).formLogin(c->c.disable()).sessionManagement(c->c.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(c->c.requestMatchers("/health").permitAll().anyRequest().authenticated()).addFilterBefore(rate,UsernamePasswordAuthenticationFilter.class).addFilterAfter(jwt,RateLimitFilter.class).build();}}